"""The welcome screen's signposts, and insights: ribbons appear only after acknowledging; a question's insight opens by
itself with every figure filled and clickable numbers; it replaces the chart's own insight; closed chart insights stay
closed until the chart changes; the setting turns both off; tours hide the card."""
import asyncio
from playwright.async_api import async_playwright
results = []
def ok(name, cond): results.append(bool(cond)); print(('PASS ' if cond else 'FAIL ') + name)
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(executable_path='/opt/pw-browsers/chromium-1194/chrome-linux/chrome', args=['--use-gl=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'])
        pg = await (await b.new_context(viewport={'width': 1600, 'height': 950})).new_page(); errs = []; pg.on('pageerror', lambda e: errs.append(str(e)[:200])); J = pg.evaluate
        await pg.goto('http://localhost:8765/test.html'); await pg.wait_for_timeout(3000)
        ok('W1 the doors stay closed until the notice is acknowledged', await J("getComputedStyle(document.querySelector('.wdoors')).pointerEvents === 'none'"))
        await pg.click('#wAckBtn'); await pg.wait_for_timeout(2200)
        ok('W2 three doors: Learn, Ask and Explore', await J("[...document.querySelectorAll('.wdoor .wdl')].map(x => x.textContent).join(',')") == 'LEARN,ASK,EXPLORE')
        await pg.click('#wLearn'); await pg.wait_for_timeout(1400)
        ok('W3 behind Learn: labelled sections, and a picture on every tour', len(await J("[...document.querySelectorAll('#wp-learn .wsec')].map(h => h.textContent)")) >= 3 and await J("document.querySelectorAll('#wp-learn .wtile svg.tpic').length") == await J("document.querySelectorAll('#wp-learn .wtile').length") >= 8)
        await J("document.querySelector('#wp-learn .wdoorsback').click()"); await pg.wait_for_timeout(500)
        await J("document.getElementById('wQuestions').click()"); await pg.wait_for_timeout(1400)
        await J("document.querySelector('#wp-ask .wlayout [data-lay=\"carousel\"]').click()"); await pg.wait_for_timeout(700)
        ok('W4 Ask can be an orbiting carousel: every question on it, each naming its section, one at the front', await J("document.querySelectorAll('#wp-ask .orbit .qtile').length === document.querySelectorAll('#wp-ask .qtile').length && document.querySelectorAll('#wp-ask .orbit .wkick').length > 0 && document.querySelectorAll('#wp-ask .orbit .qtile.ofront').length === 1"))
        await J("document.querySelector('#wp-ask .wdoorsback').click()"); await pg.wait_for_timeout(300); await J("document.getElementById('wLearn').click()"); await pg.wait_for_timeout(1400)
        ok('W5 Learn keeps its own choice (still tiles), and the choice is in the view for My file', await J("!document.querySelector('#wp-learn .orbit') && __getT().view.askLayout === 'carousel' && !__getT().view.learnLayout"))
        await J("document.querySelector('#wp-learn .wlayout [data-lay=\"carousel\"]').click()"); await pg.wait_for_timeout(700)
        ok('W6 as a carousel, this week’s analyses stay as tiles', await J("!!document.querySelector('#wp-learn .wtiles.wide') && !document.querySelector('#wp-learn .orbit [data-tour=\"week\"]') && !!document.querySelector('#wp-learn .orbit')"))
        await J("document.querySelector('#wp-learn .wlayout [data-lay=\"tiles\"]').click(); document.querySelector('#wp-learn .wdoorsback').click()"); await pg.wait_for_timeout(500)
        await J("document.getElementById('wQuestions').click()"); await pg.wait_for_timeout(1400); await J("document.querySelector('#wp-ask .wlayout [data-lay=\"tiles\"]').click()"); await pg.wait_for_timeout(600)
        for _ in range(3):   # back to the doors, from whichever page is showing
            if await J("document.getElementById('welcome').dataset.page === 'doors'"): break
            await J("[...document.querySelectorAll('.wdoorsback')].forEach(b => { if (b.offsetParent) b.click(); })"); await pg.wait_for_timeout(700)
        await pg.wait_for_selector('#wQuestions', state='visible', timeout=8000)
        await pg.click('#wQuestions'); await pg.wait_for_timeout(1600)
        await J("document.querySelector('.qtile[data-q=\"clean-ai\"]').click()"); await pg.wait_for_timeout(2500)
        ok('Q1 the question’s insight opens by itself', await J("document.getElementById('qInsight').classList.contains('on')"))
        ok('Q2 every figure is filled', not await J("/\\{/.test(document.querySelector('#qInsight .qitext').textContent)") and len(await J("document.querySelectorAll('#qInsight .colink')")) if False else not await J("/\\{/.test(document.querySelector('#qInsight .qitext').textContent)"))
        ok('Q3 its numbers can be selected', await J("document.querySelectorAll('#qInsight .colink').length") >= 2)
        ok('Q4 it replaces the chart’s own insight', not await J("document.getElementById('chartCallout').classList.contains('on')"))
        await J("document.querySelector('#chartTabs button[data-t=\"heat\"]').click()"); await pg.wait_for_timeout(800)
        ok('C1 a new chart opens its insight', await J("document.getElementById('chartCallout').classList.contains('on')"))
        await J("document.getElementById('coX').click()"); await pg.wait_for_timeout(800)
        ok('C2 closed, it stays closed', not await J("document.getElementById('chartCallout').classList.contains('on')"))
        # Speak becomes Stop while speaking; Mute speech silences insights and walk-throughs together
        await J("(() => { window.__said = []; speechSynthesis.speak = u => { window.__said.push(u.text); window.__u = u; }; })()")
        await J("document.querySelector('#chartTabs button[data-t=\"pipe\"]').click()"); await pg.wait_for_timeout(800)
        await J("document.getElementById('coSpeak').click()"); await pg.wait_for_timeout(300)
        ok('P1 Speak becomes Stop while speaking', await J("document.getElementById('coSpeak').textContent") == '■ Stop')
        await J("document.getElementById('coSpeak').click()"); await pg.wait_for_timeout(300)
        ok('P2 Stop ends it', await J("document.getElementById('coSpeak').textContent") == '🔊 Speak')
        await J("document.getElementById('presentBtn').click()"); await pg.wait_for_timeout(200); await J("document.querySelector('#presentMenu [data-act=\"mutespeech\"]').click()"); await pg.wait_for_timeout(500)
        ok('P3 Mute speech shows a chip and mutes the walk-throughs too', await J("!!document.querySelector('#tbChips [data-chip=\"mutespeech\"]')") and await J("__getT().tour.muted === true"))
        n = await J("window.__said.length"); await J("document.getElementById('coSpeak').click()"); await pg.wait_for_timeout(300)
        ok('P4 while muted, Speak stays silent', await J("window.__said.length") == n and await J("document.getElementById('coSpeak').textContent") == '🔊 Speak')
        await J("document.querySelector('#tbChips [data-chip=\"mutespeech\"]').click()"); await pg.wait_for_timeout(400)
        ok('P5 its chip turns speech back on', await J("!__getT().view.muteSpeech && !__getT().tour.muted"))
        await J("(() => { const s = document.getElementById('autoInsS'); s.value = 'off'; s.dispatchEvent(new Event('change')); })()"); await pg.wait_for_timeout(300)
        await J("document.querySelector('#chartTabs button[data-t=\"ai\"]').click()"); await pg.wait_for_timeout(800)
        ok('S1 with the setting off, insights stay closed', not await J("document.getElementById('chartCallout').classList.contains('on')") and not await J("document.getElementById('qInsight').classList.contains('on')"))
        await J("(() => { const s = document.getElementById('autoInsS'); s.value = 'on'; s.dispatchEvent(new Event('change')); })()")
        await J("document.getElementById('questionsBtn').click(); document.querySelector('#questionsMenu [data-qm=\"__all\"]').click()"); await pg.wait_for_timeout(1400)
        await J("document.querySelector('.qtile[data-q=\"changed\"]').click()"); await pg.wait_for_timeout(2500)
        ok('Q5 a question without a chart still has its insight', await J("document.getElementById('qInsight').classList.contains('on')"))
        await J("document.getElementById('toursBtn').click()"); await pg.wait_for_timeout(500); await J("__getT().tour && 0"); await J("document.querySelector('.wcard[data-tour=\"gap\"]').click()"); await pg.wait_for_timeout(1500)
        ok('T1 tours hide the insight card', await J("getComputedStyle(document.getElementById('qInsight')).display === 'none'"))
        ok('X1 no page errors', not errs)
        print(f"PASSED {sum(results)} of {len(results)} | page errors: {errs}")
        await b.close()
asyncio.run(main())
